def slug(value: str) -> str:
    normalized = re.sub(r"[^a-z0-9]+", "_", value.lower()).strip("_")
    return normalized[:48] or "gate"


def stage_from_headings(headings: dict[int, str]) -> str:
    return slug(headings.get(2, "unscoped"))


def discover_gates(content: str) -> list[dict]:
    headings: dict[int, str] = {}
    gates = []
    seen = set()
    for line_number, line in enumerate(content.splitlines(), start=1):
        heading = HEADING.match(line)
        if heading:
            level = len(heading.group(1))
            headings[level] = heading.group(2).strip()
            for key in tuple(headings):
                if key > level:
                    del headings[key]
            continue
        checkbox = CHECKBOX.match(line)
        if not checkbox:
            continue
        raw_label = checkbox.group(4).strip()
        metadata = {
            "kind": "generic", "verification_check": "",
            "capability": "", "pid_sensitive": False, "gate_key": "",
            "generation": 1, "supersedes": [],
        }
        label = raw_label
        while True:
            matched = False
            for marker in GATE_METADATA_MARKERS:
                found = marker.search(label)
                if not found:
                    continue
                value = found.group(1)
                if marker is GATE_KIND_MARKER:
                    metadata["kind"] = value
                elif marker is GATE_VERIFICATION_CHECK_MARKER:
                    metadata["verification_check"] = value
                elif marker is GATE_CAPABILITY_MARKER:
                    metadata["capability"] = value
                elif marker is GATE_PID_SENSITIVE_MARKER:
                    metadata["pid_sensitive"] = value == "true"
                elif marker is GATE_KEY_MARKER:
                    metadata["gate_key"] = value
                elif marker is GATE_GENERATION_MARKER:
                    metadata["generation"] = int(value)
                else:
                    metadata["supersedes"] = value.split(",")
                label = label[:found.start()].rstrip()
                matched = True
                break
            if not matched:
                break
        kind = metadata["kind"]
        if (
            "(only-if-frontend)" in label.lower()
            and FRONTEND_NOT_PRESENT_MARKER not in label.lower()
        ):
            metadata["capability"] = "frontend"
        if not label:
            raise GateError(f"Gate label is empty at TODO line {line_number}")
        if kind not in ALL_MACHINE_GATE_KINDS | {"generic"}:
            raise GateError(f"unsupported machine Gate kind at TODO line {line_number}: {kind}")
        path = " / ".join(headings[key] for key in sorted(headings))
        raw = f"{path}\0{label}".encode("utf-8")
        gate_id = f"{stage_from_headings(headings)}.{slug(label)}.{sha256_bytes(raw)[:8]}"
        gate_key = metadata["gate_key"] or gate_id
        if gate_id in seen:
            raise GateError(f"duplicate generated gate ID at TODO line {line_number}")
        seen.add(gate_id)
        gates.append({
            "gate_id": gate_id,
            "stage": stage_from_headings(headings),
            "label": label,
            "kind": kind,
            "verification_check": metadata["verification_check"],
            "capability": metadata["capability"],
            "pid_sensitive": metadata["pid_sensitive"],
            "gate_key": gate_key,
            "generation": metadata["generation"],
            "supersedes": metadata["supersedes"],
            "line": line_number,
        })
    if not gates:
        raise GateError("session TODO contains no checkboxes")
    return gates


def load_state(project: Path, session: str) -> dict:
    path = state_path(project, session)
    if not path.exists():
        return {
            "contract_version": CONTRACT_VERSION,
            "session_id": session,
            "todo_path": f".domainry/development/{session}.md",
            "gates": {},
            "findings": {},
            "updated_at": now(),
        }
    if path.is_symlink() or not path.is_file():
        raise GateError("development gate state is unsafe")
    document = json.loads(path.read_text(encoding="utf-8"))
    if document.get("contract_version") != CONTRACT_VERSION or document.get("session_id") != session:
        raise GateError("development gate state contract differs")
    if not isinstance(document.get("gates"), dict) or not isinstance(document.get("findings"), dict):
        raise GateError("development gate state is invalid")
    return document


def sync_gates(project: Path, session: str, state: dict) -> dict:
    path = todo_path(project, session)
    discovered = discover_gates(path.read_text(encoding="utf-8"))
    active = set()
    current = identities(project)
    for item in discovered:
        gate_id = item["gate_id"]
        active.add(gate_id)
        existing = state["gates"].get(gate_id, {})
        state["gates"][gate_id] = {
            "gate_id": gate_id,
            "stage": item["stage"],
            "label": item["label"],
            "kind": item["kind"],
            "verification_check": item.get("verification_check", ""),
            "capability": item.get("capability", ""),
            "pid_sensitive": item.get("pid_sensitive", False),
            "gate_key": item["gate_key"],
            "generation": item["generation"],
            "supersedes": item["supersedes"],
            "superseded_by": "",
            "todo_line": item["line"],
            "status": existing.get("status", "pending"),
            "evidence_type": existing.get("evidence_type", ""),
            "evidence": existing.get("evidence", []),
            "bindings": existing.get("bindings", []),
            "requirements_sha": existing.get("requirements_sha", ""),
            "source_sha": existing.get("source_sha", ""),
            "blueprint_sha": existing.get("blueprint_sha", ""),
            "runtime_manifest_sha": existing.get("runtime_manifest_sha", ""),
            "runtime_cohort_sha": existing.get("runtime_cohort_sha", ""),
            "runtime_instance_sha": existing.get("runtime_instance_sha", ""),
            "identity_migrations": existing.get("identity_migrations", []),
            "verified_at": existing.get("verified_at", ""),
            "note": existing.get("note", ""),
            "active": True,
        }
    for gate_id, gate in state["gates"].items():
        if gate_id not in active:
            gate["active"] = False
            gate.setdefault("gate_key", gate_id)
            gate.setdefault("generation", 1)
            gate.setdefault("supersedes", [])
            gate["superseded_by"] = ""
    apply_gate_supersession(state)
    typed = [item for item in discovered if item["kind"] in RUNTIME_GATE_KINDS]
    typed_kinds = [item["kind"] for item in typed]
    if typed and typed_kinds != ["runtime_start", "runtime_status"]:
        raise GateError(
            "machine Runtime Gates must be exactly one runtime_start followed by one runtime_status"
        )
    state["current_identity"] = current
    state["updated_at"] = now()
    return state


def gate_lineage_contract(gate: dict) -> tuple:
    """Fields a later generation may not weaken while replacing an older Gate."""
    return (
        gate.get("kind", "generic"), gate.get("verification_check", ""),
        gate.get("capability", ""), bool(gate.get("pid_sensitive", False)),
        REQUIREMENT_COVERAGE_MARKER in gate.get("label", "").lower(),
        mandatory_gate(gate.get("label", ""), gate.get("kind", "generic")),
    )


def apply_gate_supersession(state: dict) -> None:
    """Mark older lineage members as audit-only without rewriting their result."""
    gates = state["gates"]
    active = [gate for gate in gates.values() if gate.get("active", True)]
    families: dict[str, list[dict]] = {}
    for gate in active:
        key = gate.get("gate_key", gate["gate_id"])
        generation = gate.get("generation", 1)
        if not isinstance(generation, int) or isinstance(generation, bool) or generation <= 0:
            raise GateError(f"Gate generation is invalid: {gate['gate_id']}")
        families.setdefault(key, []).append(gate)
    for key, family in families.items():
        generations = [gate["generation"] for gate in family]
        if len(set(generations)) != len(generations):
            raise GateError(f"Gate lineage has duplicate generation for gate-key {key}")
        contracts = {gate_lineage_contract(gate) for gate in family}
        if len(contracts) != 1:
            raise GateError(f"Gate lineage changes protected capability/coverage metadata: {key}")
        authority = max(family, key=lambda gate: gate["generation"])
        for gate in family:
            if gate["generation"] < authority["generation"]:
                gate["superseded_by"] = authority["gate_id"]
    for authority in active:
        for target_id in authority.get("supersedes", []):
            target = gates.get(target_id)
            if target is None:
                raise GateError(
                    f"Gate explicit supersedes target is unknown: {authority['gate_id']} -> {target_id}"
                )
            if authority["generation"] <= target.get("generation", 1):
                raise GateError("Gate explicit supersession requires a strictly newer generation")
            if authority.get("gate_key", authority["gate_id"]) != target.get("gate_key", target["gate_id"]):
                raise GateError("Gate explicit supersession requires the same stable gate-key")
            if gate_lineage_contract(authority) != gate_lineage_contract(target):
                raise GateError("Gate explicit supersession changes protected capability/coverage metadata")
            target["superseded_by"] = authority["gate_id"]


