def gate_recovery_detail(project: Path, gate: dict, effective: str, current: dict) -> tuple[list[str], dict]:
    invalidated_inputs = []
    action = {
        "gate_id": gate["gate_id"], "gate_key": gate.get("gate_key", gate["gate_id"]),
        "generation": gate.get("generation", 1), "stage": gate.get("stage", ""),
    }
    for binding in gate.get("bindings", []):
        key = f"{binding}_sha" if binding != "runtime" else "runtime_manifest_sha"
        if gate.get(key) != current.get(key):
            invalidated_inputs.append(binding)
    if effective in {"failed", "stale"} and gate.get("evidence_type") == "command_receipt":
        try:
            receipt, item = attached_command_receipt(project, gate)
            argv = receipt.get("argv", receipt.get("command", []))
            if isinstance(argv, list) and argv and all(isinstance(value, str) for value in argv):
                action.update({
                    "action": "create_next_generation_and_run",
                    "command_argv": argv,
                    "cwd": receipt.get("cwd", "."),
                    "bindings": receipt.get("bindings", gate.get("bindings", [])),
                    "source_receipt": item["path"],
                    "next_gate_metadata": {
                        "gate_key": gate.get("gate_key", gate["gate_id"]),
                        "generation": gate.get("generation", 1) + 1,
                        "supersedes": gate["gate_id"],
                    },
                })
                if effective == "failed":
                    error = receipt.get("expectation", {}).get("error", "")
                    if error:
                        action["failure"] = str(error)[:MAX_FAILURE_REASON_CHARS]
        except (GateError, OSError, json.JSONDecodeError) as error:
            invalidated_inputs.append("attached_evidence")
            action.update({"action": "repair_evidence_contract", "diagnosis": str(error)})
    elif effective == "pending":
        action["action"] = "complete_current_gate"
    elif effective == "accepted_limitation":
        action["action"] = "resolve_current_limitation"
    else:
        action["action"] = "refresh_current_gate_evidence"
    return sorted(set(invalidated_inputs)), action


def build_recovery_plan(project: Path, state: dict, status: dict, limit: int) -> dict:
    current = dict(status["current_identity"], project=project)
    gates = state["gates"]
    blockers = status["blocking_gates"]
    chain = []
    actions = []
    stages = []
    for row in blockers:
        gate = gates[row["gate_id"]]
        invalidated_inputs, action = gate_recovery_detail(
            project, gate, row["effective_status"], current,
        )
        reason = {
            "failed": "current_generation_failed",
            "pending": "current_generation_pending",
            "stale": "bound_input_changed",
            "accepted_limitation": "current_limitation_open",
        }.get(row["effective_status"], "current_gate_blocked")
        chain.append({
            "gate_id": gate["gate_id"], "gate_key": gate.get("gate_key", gate["gate_id"]),
            "generation": gate.get("generation", 1), "stage": gate.get("stage", ""),
            "effective_status": row["effective_status"], "reason": reason,
            "invalidated_inputs": invalidated_inputs,
        })
        actions.append(action)
        if gate.get("stage", "") not in stages:
            stages.append(gate.get("stage", ""))
    earliest = None
    if blockers:
        gate = min(
            (gates[row["gate_id"]] for row in blockers),
            key=lambda value: value.get("todo_line", 0),
        )
        earliest = {
            "gate_id": gate["gate_id"], "gate_key": gate.get("gate_key", gate["gate_id"]),
            "generation": gate.get("generation", 1), "stage": gate.get("stage", ""),
            "todo_line": gate.get("todo_line", 0),
        }
    return {
        "current_blockers": blockers,
        "invalidation_chain": chain,
        "earliest_recovery_checkpoint": earliest,
        "rerun_plan": {
            "bounded": True, "limit": limit, "stages": stages,
            "actions": actions,
            "truncated": status["blocking_gate_count"] > len(blockers),
        },
    }


def status_document(project: Path, state: dict, stage: str = "", limit: int = 20) -> dict:
    current = dict(identities(project), project=project)
    rows = []
    counts = {status: 0 for status in EFFECTIVE_STATUSES}
    for gate in state["gates"].values():
        if not gate.get("active", True) or (stage and gate["stage"] != stage):
            continue
        effective = effective_status(gate, current)
        counts[effective] += 1
        rows.append({
            "gate_id": gate["gate_id"],
            "stage": gate["stage"],
            "label": gate["label"],
            "kind": gate.get("kind", "generic"),
            "gate_key": gate.get("gate_key", gate["gate_id"]),
            "generation": gate.get("generation", 1),
            "superseded_by": gate.get("superseded_by", ""),
            "declared_status": gate["status"],
            "effective_status": effective,
        })
    findings = [value for value in state["findings"].values() if not stage or value.get("stage") == stage]
    blocking_findings = [value for value in findings if value.get("status") in {"open", "accepted_limitation"}]
    blocking_gates = [value for value in rows if value["effective_status"] in BLOCKING]
    document = {
        "contract_version": CONTRACT_VERSION,
        "state": "passed" if not blocking_gates and not blocking_findings else "blocked",
        "checkpoint_semantics": "phase_correctness_and_recovery_evidence",
        "agent_should_stop": False,
        "recovery_action": (
            "In the same Host/Agent session and TODO, diagnose blocking owners, repair them, "
            "add round-specific Gates for terminal failed commands, sync, rerun invalidated "
            "checks, and retry require-complete."
        ),
        "stage": stage or "all",
        "counts": counts,
        "blocking_gate_count": len(blocking_gates),
        "blocking_finding_count": len(blocking_findings),
        "blocking_gates": blocking_gates[:limit],
        "blocking_findings": blocking_findings[:limit],
        "blocking_results_truncated": len(blocking_gates) > limit or len(blocking_findings) > limit,
        "current_identity": {key: value for key, value in current.items() if key != "project"},
    }
    document.update(build_recovery_plan(project, state, document, limit))
    return document


