def attached_command_receipt(project: Path, gate: dict) -> tuple[dict, dict]:
    evidence = gate.get("evidence")
    if gate.get("evidence_type") != "command_receipt" or not isinstance(evidence, list) or len(evidence) != 1:
        raise GateError("command Gate must have exactly one attached receipt")
    item = evidence[0]
    validate_artifact_reference(project, item, "attached command receipt")
    document = command_receipt_document(project, item)
    expectation = document.get("expectation")
    if (
        document.get("contract_version") != COMMAND_RECEIPT_VERSION
        or document.get("gate_id") != gate.get("gate_id")
        or not isinstance(expectation, dict)
        or not isinstance(expectation.get("met"), bool)
        or isinstance(document.get("exit_code"), bool)
        or not isinstance(document.get("exit_code"), int)
    ):
        raise GateError("attached command receipt contract is invalid")
    return document, item


def historical_passing_command_receipts(
    project: Path, session: str, gate_id: str,
) -> list[tuple[dict, dict]]:
    root = evidence_root(project, session)
    if not root.is_dir() or root.is_symlink():
        return []
    paths = sorted(root.glob("*.json"))
    if len(paths) > MAX_SESSION_COMMAND_RECEIPTS:
        raise GateError("development Gate command receipt inventory exceeds its bound")
    found = []
    for path in paths:
        if path.is_symlink() or not path.is_file() or path.stat().st_size > MAX_COMMAND_RECEIPT_BYTES:
            continue
        try:
            document = json.loads(path.read_text(encoding="utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            continue
        if (
            not isinstance(document, dict)
            or document.get("contract_version") != COMMAND_RECEIPT_VERSION
            or document.get("gate_id") != gate_id
            or document.get("expectation", {}).get("met") is not True
        ):
            continue
        found.append((document, evidence_item(project, str(path))))
    return sorted(
        found, key=lambda value: (str(value[0].get("completed_at", "")), value[1]["path"]),
        reverse=True,
    )


def failed_gate_recovery_candidate(
    project: Path, session: str, gate: dict, current: dict, runtime: dict,
) -> tuple[dict | None, str]:
    for document, item in historical_passing_command_receipts(
        project, session, gate["gate_id"],
    ):
        candidate = dict(gate)
        candidate.update({
            "status": "passed", "evidence_type": "command_receipt", "evidence": [item],
            "bindings": list(document.get("bindings", [])),
            "requirements_sha": document.get("identity", {}).get("requirements_sha", ""),
            "source_sha": document.get("identity", {}).get("source_sha", ""),
            "blueprint_sha": document.get("identity", {}).get("blueprint_sha", ""),
            "runtime_manifest_sha": document.get("identity", {}).get("runtime_manifest_sha", ""),
            "runtime_cohort_sha": document.get("identity", {}).get("runtime_cohort_sha", ""),
            "runtime_instance_sha": document.get("identity", {}).get("runtime_instance_sha", ""),
            "note": "[machine] restored prior successful receipt after failed reconcile attempt",
        })
        try:
            command_receipt_for_migration(project, candidate, item, current, runtime)
        except (GateError, OSError, json.JSONDecodeError):
            continue
        return candidate, item["path"]
    return None, ""


def gate_input_integrity_failures(project: Path, state: dict) -> list[dict]:
    failures = []
    for gate in state["gates"].values():
        if not gate.get("active", True) or not gate.get("evidence"):
            continue
        try:
            for item in gate["evidence"]:
                validate_artifact_reference(project, item, "attached Gate evidence")
            if gate.get("evidence_type") == "command_receipt":
                attached_command_receipt(project, gate)
        except (GateError, OSError, json.JSONDecodeError) as error:
            failures.append({
                "gate_id": gate["gate_id"], "state": "unrecoverable",
                "classification": {
                    "class": "input_contract_corruption", "retryable": False,
                    "owner": "receipt_owner", "diagnosis": str(error),
                },
            })
    return failures


