            return None
        if not loopback_address(values["--address"]):
            return None
        try:
            package = json.loads((project / PACKAGE_RECEIPT).read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            return None
        if not isinstance(package, dict) or package.get("bundle_path") != bundle:
            return None
    return values


def command_kind(gate: dict, command: list[str], project: Path) -> str:
    label = gate["label"]
    declared_kind = gate.get("kind", "generic")
    lowered = label.lower()
    runtime_operation = (
        command[2] if len(command) >= 3 and Path(command[0]).name in {"domainry-cli", "domainry-cli.exe"}
        and command[1] == "runtime-process" else ""
    )
    if declared_kind in RUNTIME_GATE_KINDS:
        operation = "start" if declared_kind == "runtime_start" else "status"
        if runtime_process_command(command, operation, project) is None:
            raise GateError(f"command does not prove Gate '{label}'")
        return declared_kind
    if declared_kind in PROJECT_DELIVERY_GATE_KINDS:
        operation = "verify" if declared_kind == "project_verify" else "package"
        if not domainry_command(command, ("project", operation), project):
            raise GateError(f"command does not prove Gate '{label}'")
        return declared_kind
    if runtime_operation in {"start", "status"}:
        expected = f"managed runtime {runtime_operation} succeeds"
        if not lowered.startswith(expected) or runtime_process_command(command, runtime_operation, project) is None:
            raise GateError(f"command does not prove Gate '{label}'")
        return f"runtime_{runtime_operation}"
    verifies_project = "project verification" in lowered or "project verify" in lowered
    packages_project = "project packaging" in lowered or "packaging pass" in lowered or "project package" in lowered
    if verifies_project and packages_project:
        raise GateError("project verification and packaging must be separate Gates")
    if verifies_project:
        if not domainry_command(command, ("project", "verify"), project):
            raise GateError(f"command does not prove Gate '{label}'")
        return "project_verify"
    if packages_project:
        if not domainry_command(command, ("project", "package"), project):
            raise GateError(f"command does not prove Gate '{label}'")
        return "project_package"
    if "project check" in lowered:
        if not domainry_command(command, ("project", "check"), project) or option_value(command, "--scope") != "actions":
            raise GateError(f"command does not prove Gate '{label}'")
        return "project_check"
    if is_source_finalization_gate(label):
        if not domainry_command(command, ("project", "source", "finalize"), project):
            raise GateError(f"command does not prove Gate '{label}'")
        return "source_finalize"
    return "generic"


def validate_command_for_gate(gate: dict, command: list[str], project: Path) -> str:
    label = gate["label"]
    kind = command_kind(gate, command, project)
    if kind != "generic":
        return kind
    lowered = " ".join(command).lower()
    label_value = f" {label.lower()} "
    if "module-focused" in label_value and "test" in label_value:
        executable = Path(command[0]).name.lower()
        if executable not in {"go", "go.exe"} or len(command) < 2 or command[1] != "test":

    current = dict(identities(project), project=project)
    pre_finalization_module_test = (
        gate.get("stage") in {"apply", "implement", "implementation"}
        and "module-focused" in lowered
        and "test" in lowered
    )
    if pre_finalization_module_test:
        for candidate in state["gates"].values():
            if (
                not candidate.get("active", True)
                or candidate.get("stage") != gate.get("stage")
                or candidate.get("todo_line", 0) >= gate.get("todo_line", 0)
            ):
                continue
            status = effective_status(candidate, current)
            if status in BLOCKING:
                raise GateError(
                    "pre-finalization module test Gate requires every preceding "
                    f"{gate.get('stage')} TODO Gate to be closed: "
                    f"{candidate['gate_id']} ({status})"
                )
        return
    finalization = next((
        value for value in state["gates"].values()
        if value.get("active", True) and is_source_finalization_gate(value.get("label", ""))
    ), None)
    if finalization is None or effective_status(finalization, current) != "passed":
        raise GateError("backend compile/test Gate requires a current local-composition finalization Gate")


def mandatory_gate(label: str, kind: str = "generic") -> bool:
    if kind in ALL_MACHINE_GATE_KINDS:
        return True
    lowered = label.lower()
    if "only-if-expected-invalid-check" in lowered:
        return False
    return bool(
        required_evidence_type(label, kind)
        or REQUIREMENT_COVERAGE_MARKER in lowered
        or "all preceding stages complete" in lowered
        or "no open" in lowered
        or "no blocked finding" in lowered
        or "no requirement remains" in lowered
    )


COMMAND_CATEGORIES = (
    ("dependency installation", ("npm ci", "npm install", "pnpm install", "yarn install")),
    ("typecheck", ("tsc ", "npm run typecheck", "pnpm typecheck", "yarn typecheck")),
    ("lint", ("npm run lint", "pnpm lint", "yarn lint", "eslint ", "golangci-lint")),
    ("test", ("npm test", "npm run test", "pnpm test", "yarn test", "vitest", "jest", "go test")),
    ("production build", ("npm run build", "pnpm build", "yarn build", "vite build")),
    ("formatting", ("gofmt", "go fmt")),
    (" vet", ("go vet",)),
)


def option_value(command: list[str], name: str) -> str:
    for index, value in enumerate(command):
        if value == name and index + 1 < len(command):
            return command[index + 1]
        if value.startswith(name + "="):
            return value.split("=", 1)[1]
    return ""


def domainry_command(command: list[str], family: tuple[str, ...], project: Path) -> bool:
    if len(command) < len(family) + 1 or Path(command[0]).name not in {"domainry-cli", "domainry-cli.exe"}:
        return False
    if tuple(command[1:1 + len(family)]) != family or "--json" not in command:
        return False

